        .qh-pathway-card--pregnancy {background: #FBF1F3; border-color: #E5CBD2; border-left-color: #A76F82;}
        .qh-pathway-card--postpartum {background: #FBF2E9; border-color: #E8D6C2; border-left-color: #A56C48;}
